#!/usr/bin/env python3
from pathlib import Path
import base64,lzma
FILES={'backend/app/domain/food_recipes.py': '', 'backend/app/services/food_recipes.py': '', 'backend/app/persistence/sqlalchemy_core/food_recipe_tables.py': '', 'backend/app/migrations/versions/0024_food_recipe_catalogue.py': '', 'backend/app/seed/food_recipes.py': ''}
for raw,payload in FILES.items():
 p=Path(raw); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(lzma.decompress(base64.b64decode(payload)))
